test('addLine and removeLine: chain operations', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  let invoice = invoiceResult.value;

  let result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 2);

  result = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 3);

  result = removeLine(invoice, 'DES-HOUR');
  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[1].sku, 'LOGO-PACK');
});

test('issueInvoice: assigns number and marks as issued', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = issueInvoice(invoice, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2025-0001');
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.customerId, invoice.customerId);
  assert.equal(result.value.issueDate, invoice.issueDate);
});

